const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '解一元一次方程 · 流程卡' },
      { kind: 'text', payload: '原方程：2x + 3 = 5x + 7' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '移项' },
      { kind: 'text', payload: '2x - 5x = 7 - 3' },
      { kind: 'text', payload: '2' },
      { kind: 'text', payload: '合并同类项' },
      { kind: 'text', payload: '-3x = 4' },
      { kind: 'text', payload: '3' },
      { kind: 'text', payload: '系数化为 1' },
      { kind: 'text', payload: 'x = -4/3' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var pad = Math.max(16, Math.min(28, w * 0.035));
    var headerH = Math.max(58, Math.min(78, h * 0.15));
    var titleX = w / 2;
    var titleY = headerH / 2;

    var cardX = pad * 0.6;
    var cardY = pad * 0.6;
    var cardW = w - cardX * 2;
    var cardH = h - cardY * 2;

    var eqX = pad + 8;
    var eqY = headerH + 16;
    var eqW = w - 2 * (pad + 8);
    var eqH = Math.max(44, Math.min(56, h * 0.10));

    var stepsTop = eqY + eqH + 18;
    var gap = Math.max(10, Math.min(16, h * 0.025));
    var stepX = pad + 8;
    var stepW = w - 2 * (pad + 8);
    var bottomPad = pad + 8;
    var stepH = (h - stepsTop - bottomPad - gap * 2) / 3;
    if (stepH > 96) stepH = 96;
    if (stepH < 62) stepH = 62;

    var colors = ['#2F6FBA', '#2E8B57', '#C26A1A'];
    var stepNumbers = [2, 5, 8];
    var stepNames = [3, 6, 9];
    var stepFormulas = [4, 7, 10];

    function rectCommands(x, y, ww, hh) {
      return [['M', x, y], ['L', x + ww, y], ['L', x + ww, y + hh], ['L', x, y + hh], ['Z']];
    }
    function roundRectCommands(x, y, ww, hh, r) {
      var rr = Math.min(r, ww / 2, hh / 2);
      return [
        ['M', x + rr, y],
        ['L', x + ww - rr, y],
        ['Q', x + ww, y, x + ww, y + rr],
        ['L', x + ww, y + hh - rr],
        ['Q', x + ww, y + hh, x + ww - rr, y + hh],
        ['L', x + rr, y + hh],
        ['Q', x, y + hh, x, y + hh - rr],
        ['L', x, y + rr],
        ['Q', x, y, x + rr, y],
        ['Z']
      ];
    }

    var paths = [];
    var children = [];

    function addPath(id, commands, fill, stroke) {
      paths.push({ id: id, commands: commands });
      var node = { type: 'path', pathId: id, fill: fill };
      if (stroke) node.stroke = stroke;
      children.push(node);
    }
    function addLabel(idx, x, y, hAlign, vAlign, color) {
      children.push({ type: 'label', contentId: metrics[idx].contentId, anchor: { x: x, y: y }, hAlign: hAlign, vAlign: vAlign, color: color });
    }

    addPath('bg', rectCommands(0, 0, w, h), '#E9F0F7');
    addPath('card', roundRectCommands(cardX, cardY, cardW, cardH, 16), '#FFFFFF');
    addPath('header', roundRectCommands(cardX, cardY, cardW, headerH, 16), '#2F5D8A');
    addPath('headerBase', rectCommands(cardX, cardY + headerH - 16, cardW, 16), '#2F5D8A');
    addPath('eqBox', roundRectCommands(eqX, eqY, eqW, eqH, 10), '#EDF4FB');

    var stepYs = [];
    for (var i = 0; i < 3; i++) {
      var y = stepsTop + i * (stepH + gap);
      stepYs.push(y);
      addPath('stepBg' + i, roundRectCommands(stepX, y, stepW, stepH, 12), '#F5F8FC');
      addPath('stepAccent' + i, roundRectCommands(stepX, y, 7, stepH, 3), colors[i]);
      addPath('stepCircle' + i, visualSdk.circle(stepX + 32, y + stepH / 2, Math.min(18, stepH * 0.27)), colors[i]);
    }

    addLabel(0, titleX, titleY, 'center', 'middle', '#FFFFFF');
    addLabel(1, w / 2, eqY + eqH / 2, 'center', 'middle', '#1F2D3D');

    for (var j = 0; j < 3; j++) {
      var yy = stepYs[j];
      var circleX = stepX + 32;
      var circleY = yy + stepH / 2;
      addLabel(stepNumbers[j], circleX, circleY, 'center', 'middle', '#FFFFFF');
      addLabel(stepNames[j], stepX + 64, yy + stepH * 0.34, 'left', 'middle', '#1F2D3D');
      addLabel(stepFormulas[j], stepX + 64, yy + stepH * 0.70, 'left', 'middle', '#34495E');
    }

    return {
      schemaVersion: 1,
      sceneId: 'equation-flow-card',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
